def project(folder,cam,xyz):
 K,T=calibration(folder,cam)
 q=(np.array(xyz)-T[:3,3])@T[:3,:3]
 q=q*np.array([1,-1,-1])
 uv=K@q
 return uv[:2]/uv[2]
